package com.sivion.api.finance.controller; import com.sivion.api.finance.service.FinanceService; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/finance") @PreAuthorize("hasAnyRole('ADMIN','FINANCE_USER','FINANCE_MANAGER')") public class FinanceController {private final FinanceService s; public FinanceController(FinanceService s){this.s=s;} @GetMapping("/invoices") public List<FinanceService.InvoiceView> invoices(){return s.invoices();} @PostMapping("/invoices") public FinanceService.InvoiceView invoice(@RequestBody FinanceService.InvoiceRequest r){return s.invoice(r);} @GetMapping("/payments") public List<FinanceService.PaymentView> payments(){return s.payments();} @PostMapping("/payments") public FinanceService.PaymentView payment(@RequestBody FinanceService.PaymentRequest r){return s.payment(r);} @GetMapping("/expenses") public List<FinanceService.ExpenseView> expenses(){return s.expenses();} @PostMapping("/expenses") public FinanceService.ExpenseView expense(@RequestBody FinanceService.ExpenseRequest r){return s.expense(r);} }
